// vehicle_odometer_readings_search.js — generated by Generate Module

$(document).ready(function () {

  const statusBadge = function (data) {
    const c = { active: 'success', inactive: 'danger' };
    return '<span class="badge text-bg-' + (c[data] || 'secondary') + '">' + data + '</span>';
  };

  // ── Vehicle picker ───────────────────────────────────────────────────────
  const vehiclePicker = $('#vodVehiclePickerTable').DataTable({
    ajax: { url: '/modules/master_files/staff_fleet/vehicle_master_file/vehicle_master_file_data.php?action=list', dataSrc: '' },
    columns: [
      { data: 'ref' },
      { data: 'plate_number' },
      { data: 'make' },
      { data: 'model' },
      { data: 'type' },
      { data: 'status', render: statusBadge },
    ],
    pageLength: 10,
    searching: true,
    dom: '<"d-flex justify-content-between align-items-center mb-2"f>rtip',
    language: { search: 'Filter:', info: 'Showing _START_ to _END_ of _TOTAL_' },
  });

  $('#vodVehiclePickerTable tbody').on('click', 'tr', function () {
    const data = vehiclePicker.row(this).data();
    if (!data) return;
    bootstrap.Modal.getInstance(document.getElementById('vodVehiclePickerModal')).hide();
    document.dispatchEvent(new CustomEvent('vod-vehicle-selected', { detail: data }));
  });

  $('#vodVehiclePickerModal').on('shown.bs.modal', function () {
    vehiclePicker.ajax.reload(null, false);
    vehiclePicker.columns.adjust();
  });

  const table = $('#vehicleOdometerReadingsSearchTable').DataTable({
    ajax: { url: '/modules/operations/fleet_maintenance/vehicle_odometer_readings/vehicle_odometer_readings_data.php?action=list', dataSrc: '' },
    columns: [
      { data: 'ref' },
      { data: 'm_vehicles.plate_number', defaultContent: '' },
      { data: 'reading_date' },
      { data: 'odometer_km' },
      { data: 'remarks' },
    ],
    pageLength: 10,
    lengthMenu: [5, 10, 25, 50],
    dom: '<"d-flex justify-content-between align-items-center mb-2"Bf>rtip',
    buttons: [
      { extend: 'copy',  className: 'btn btn-sm btn-secondary' },
      { extend: 'excel', className: 'btn btn-sm btn-success',  text: '<i class="bi bi-file-earmark-excel me-1"></i>Excel' },
      { extend: 'csv',   className: 'btn btn-sm btn-info',     text: '<i class="bi bi-filetype-csv me-1"></i>CSV' },
      { extend: 'pdf',   className: 'btn btn-sm btn-danger',   text: '<i class="bi bi-file-earmark-pdf me-1"></i>PDF' },
      { extend: 'print', className: 'btn btn-sm btn-secondary' },
    ],
    language: {
      search: 'Global search:',
      lengthMenu: 'Show _MENU_ entries',
      info: 'Showing _START_ to _END_ of _TOTAL_ Vehicle Odometer Readings records',
    },
  });

  $('#vehicleOdometerReadingsSearchTable tbody').on('click', 'tr', function () {
    const data = table.row(this).data();
    if (!data) return;
    bootstrap.Modal.getInstance(document.getElementById('vehicleOdometerReadingsSearchModal')).hide();
    document.dispatchEvent(new CustomEvent('vehicle_odometer_readings-selected', { detail: data }));
  });

  $('#vehicleOdometerReadingsSearchModal').on('shown.bs.modal', function () {
    table.ajax.reload(null, false);
    table.columns.adjust();
  });

});
